import { Component, createEffect, createSignal, For, mergeProps } from "solid-js";

import {
	getPlayerDiplomacy,
	getRelationship,
	getRelationshipIconFromPlayer,
	PlayerRelationship,
} from "#core/ui/utilities/diplomacy-utilities.js";
import { FiligreeTitle } from "#core/ui-next/components/filigree-title.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface RelationshipBreakdownProps {
	playerId: PlayerId;
	comparisonPlayerId?: PlayerId;
}

interface RelationshipItem {
	eventType: DiplomacyFavorGrievanceEventType;
	amount: number;
	triggeredBy: PlayerId;
}

const RelationshipBreakdownComponent: Component<RelationshipBreakdownProps> = (props) => {
	const [relationship, setRelationship] = createSignal<PlayerRelationship>({
		type: DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_UNKNOWN,
		levelName: "unknown",
		amount: 0,
	});
	const [relationshipItems, setRelationshipItems] = createSignal<RelationshipItem[]>([]);

	const propsWithDefaults = mergeProps({ comparisonPlayerId: GameContext.localPlayerID }, props);

	createEffect(() => {
		setRelationship(getRelationship(propsWithDefaults.playerId, propsWithDefaults.comparisonPlayerId));
		const playerDiplomacy = getPlayerDiplomacy(propsWithDefaults.playerId);
		if (!playerDiplomacy) {
			console.error(
				"RelationshipBreakdownComponent: Can't find diplomacy object for player",
				propsWithDefaults.playerId,
			);
			return;
		}

		if (propsWithDefaults.comparisonPlayerId == PlayerIds.NO_PLAYER) {
			console.error("RelationshipBreakdownComponent: comparisonPlayerId is NO_PLAYER");
			return;
		}

		const relationshipHistory = playerDiplomacy.getPlayerRelationshipHistory(propsWithDefaults.comparisonPlayerId);
		if (!relationshipHistory) {
			console.error(
				"RelationshipBreakdownComponent: Can't find relationshipHistory between players",
				propsWithDefaults.playerId,
				"and",
				propsWithDefaults.comparisonPlayerId,
			);
			return;
		}

		const relationshipItemList: RelationshipItem[] = [];
		for (const historyItem of relationshipHistory) {
			const itemIndex = relationshipItemList.findIndex((item) => historyItem.eventType == item.eventType && historyItem.triggeredBy == item.triggeredBy);
			if (itemIndex != -1) {
				relationshipItemList[itemIndex].amount += historyItem.amount;
			} else {
				relationshipItemList.push({
					eventType: historyItem.eventType,
					amount: historyItem.amount,
					triggeredBy: historyItem.triggeredBy,
				});
			}
		}

		relationshipItemList.sort((a, b) => {
			if (a.eventType != b.eventType) {
				return b.eventType - a.eventType;
			}
			return b.triggeredBy - a.triggeredBy;
		});

		setRelationshipItems(relationshipItemList);
	});

	const addPlusIfNeeded = (num: number) => {
		return `${num > 0 ? "+" : ""}` + num;
	};
	return (
		<div
			class="relationship-breakdown-container"
			data-name="Relationship-Breakdown"
		>
			<div class="relationship-breakdown__Header flex flex-col items-center justify-center w-full">
				<FiligreeTitle.H4
					class="relationship-breakdown__title mb-1 flex items-center"
					text="LOC_INDEPENDENT_RELATIONSHIP"
				/>
				<div class="relationship-breakdown__info flex items-center">
					<Icon
						class="size-8"
						name={getRelationshipIconFromPlayer(propsWithDefaults.playerId)}
						isUrl={true}
					/>
					<div class="mx-2">
						<L10n.Compose text={relationship().levelName} />
					</div>
					<div
						classList={{
							"text-positive": relationship().amount > 0,
							"text-negative": relationship().amount < 0,
						}}
						class="mr-2"
					>
						{relationship().amount > 0 ? `+${relationship().amount}` : relationship().amount}
					</div>
				</div>
			</div>
			<Filigree.GoldFrame
				topClass="relationship-breakdown__section-line-above mt-2"
				bottomClass="relationship-breakdown__section-line-below"
				hideDecoration={relationshipItems().length === 0}
			>
				<div class="relationship-breakdown__relationship-items-container flex flex-col px-2">
					<For each={relationshipItems()}>
						{(relationshipItem, index) => (
							<div
								class="event-line flex justify-between p-1"
								classList={{ "bg-primary-3": index() % 2 === 0 }}
							>
								<div
									class="event-text flex-1 pr-4"
									classList={{ "text-accent-1": index() % 2 !== 0 }}
								>
									<L10n.Stylize
										text={
											getPlayerDiplomacy(
												propsWithDefaults.comparisonPlayerId,
											)?.getFavorGrievanceEventTypeName(relationshipItem.eventType, relationshipItem.triggeredBy) ?? ""
										}
									/>
								</div>
								<div
									class="event-amount font-bold"
									classList={{
										"text-positive": relationshipItem.amount > 0,
										"text-negative": relationshipItem.amount < 0,
									}}
								>
									{addPlusIfNeeded(Math.floor(relationshipItem.amount * 10) / 10)}
								</div>
							</div>
						)}
					</For>
				</div>
			</Filigree.GoldFrame>
		</div>
	);
};

export const RelationshipBreakdown = ComponentRegistry.register({
	name: "RelationshipBreakdown",
	createInstance: RelationshipBreakdownComponent,
});
